-- Seeding all 18 study topics and 102 topic words with examples

ON DUPLICATE KEY UPDATE 
    title = VALUES(title),
    category = VALUES(category),
    item_count_text = VALUES(item_count_text);

DELETE FROM topic_words;

UPDATE study_topics st
SET item_count_text = CONCAT(
    (SELECT COUNT(*) FROM topic_words tw WHERE tw.topic_code = st.topic_code),
    ' mục'
);

